    var d1 = new THREE.DirectionalLight(0xffffff, 0.78); d1.position.set(-4 * t, 7 * t, 5 * t);
    var d2 = new THREE.DirectionalLight(0xc8dcff, 0.34); d2.position.set(5 * t, 3 * t, -6 * t);
    h.name = 'm3d-hemi'; d1.name = 'm3d-cle'; d2.name = 'm3d-contre';
    scene.add(h); scene.add(d1); scene.add(d2);
    return [h, d1, d2];
