    C.lourd = d.carburant === 'diesel' && d.arch !== 'ET' && ((d.cylindreeL || 0) / Math.max(1, d.cyl || 1) >= 1.1 || /camion|bus|tracteur|engin|lourd/.test(d.categorie || ''));
