      if (Math.abs(aa) < 1e-9) xx = -cc / bb; else { var disc = bb * bb - 4 * aa * cc; if (disc >= 0) xx = (-bb - Math.sqrt(disc)) / (2 * aa); }
      if (xx > 0.2 && xx < rg * 1.3 && (nI - 1) * xx < D - rg){ ri = xx; break; }
