    if (air){
      aj(nomF, 'aluF', fTour(cle('capotE', Rs, tc), [[0, -0.30 * Rs], [Rs * 1.1, -0.30 * Rs], [Rs * 1.16, -0.02 * Rs], [Rs * 1.16, 0], [0, 0]], seg, true), mUnite(U, mAxe([0, 0, -lh / 2], [0, 0, 1])));
      aj(nomF, 'aluF', fCyl(Rs * 0.8, Rs * 0.8, 0.02 * Rs, seg), mUnite(U, mAxe([0, 0, -lh / 2 - 0.31 * Rs], [0, 0, 1])));
    } else {
      aj(nomF, 'aluF', fTour(cle('flasqueE', Rh, tc, rr), [[0, -tc], [Rh * 0.75, -tc], [Rh, -tc * 0.4], [Rh, 0], [0, 0]], seg, true), mUnite(U, mAxe([0, 0, -lh / 2], [0, 0, 1])));
      aj(nomF, 'aluF', fCyl(0.30 * rr, 0.30 * rr, 0.10 * rr, 12), mUnite(U, mAxe([0, 0, -lh / 2 - tc - 0.05 * rr], [0, 0, 1])));
    }
