    var hO = 0.28 * Rs, lO = lh * 0.60, wO = Math.min(1.25 * Rs, 1.8 * Rh), yO = yT + hO / 2 - 0.04 * Rs, zO = -lh * 0.17;
    aj('onduleur', 'noir', fBoite(wO, hO, lO), mUnite(U, mPos(0, yO, zO)));
    aj('onduleur', 'noir', fBoite(wO * 1.04, 0.05 * Rs, lO * 1.03), mUnite(U, mPos(0, yO + hO / 2 + 0.02 * Rs, zO)));
    aj('carterElec', 'alu', fBoite(0.46 * Rs, 0.22 * Rs, 0.30 * Rs), mUnite(U, mPos(0, yT + 0.06 * Rs, lh * 0.33)));
