    if (!U.leger) for (var ph = -1; ph <= 1; ph++) tige(C, LN('cablesHT'), LM('orange'), pUnite(U, [ph * 0.13 * Rs, yT + 0.09 * Rs, zO + lO / 2 - 0.02 * Rs]), pUnite(U, [ph * 0.13 * Rs, yT + 0.09 * Rs, lh * 0.33 - 0.14 * Rs]), 0.035 * Rs, 8);
    U.ond = { c: pUnite(U, [0, yO, zO]), w: wO, h: hO, l: lO };
