      if (montSegTri(tb[ob + k * 3], tb[ob + k * 3 + 1], tb[ob + k * 3 + 2], tb[ob + k2 * 3], tb[ob + k2 * 3 + 1], tb[ob + k2 * 3 + 2], _triD, 0, 1e-7)) return true;
