    A.levM = 0;
    montPoserTemps(A, Mt, true);
    montVisibilites(A, Mt);     // V1.2.2 (ASSEMBLER L1, reprise) : apres montPoserTemps, qui dit les pieces pas encore parties
    if (A.levM !== lv) montReposer(A);
