  function xAlim(C){ return xR(C, 'alim'); }
  function alimCarbN(C){ var a = xAlim(C); return (a && a.carbN === 2) ? 2 : 0; }
  function alimKCarb(C){ return xNum(xAlim(C), 'kCarb', 0.85, 1.20); }
  function alimInjN(C){ var a = xAlim(C); return (a && a.injN === 2) ? 2 : 0; }
  /* allumage : type (allumeur 'vis' / 'elec', bobines 'bob') et bougies par cylindre (par rotor) */
  function xAllum(C){ return xR(C, 'allum'); }
  function allumType(C){ var a = xAllum(C), t = a && a.type; return (t === 'vis' || t === 'elec' || t === 'bob') ? t : ''; }
  function allumN(C){ var a = xAllum(C); return (a && (a.n === 1 || a.n === 2)) ? a.n : 0; }
  /* turbo : taille de turbine / reference, compresseur / turbine, A/R / 0,63 */
  function xTurbo(C){ return xR(C, 'turbo'); }
  function turboKT(C){ return xNum(xTurbo(C), 'kT', 0.80, 1.45); }
  function turboKC(C){ return xNum(xTurbo(C), 'kC', 0.85, 1.25); }
  function turboAR(C){ return xNum(xTurbo(C), 'ar', 0.76, 1.68); }
  /* compresseur mecanique : embrayage sur la poulie */
  function cmpEmbr(C){ var c = xR(C, 'cmp'); return !!(c && c.embr === true); }

  /* ---------- petits outils de vecteurs ---------- */
  function v3(a, b, k){ return [a[0] + b[0] * k, a[1] + b[1] * k, a[2] + b[2] * k]; }
  function n3(a){ var l = Math.sqrt(a[0] * a[0] + a[1] * a[1] + a[2] * a[2]) || 1; return [a[0] / l, a[1] / l, a[2] / l]; }
