      ajout(C, 'admission', 'noir', fCyl(0.12 * S, 0.12 * S, 0.16 * S, C.seg), mAxe([xP - rT - 0.07 * S, yP, za], [-1, 0, 0]));
      tige(C, 'admission', 'acier', [xP - rT - 0.02 * S, yP, za], [xP - rT - 0.02 * S, yP, -z0 - 0.10 * R], 0.03 * S, 6);
