    if (k) deps.forEach(function(s){ if (!s || s.chemin) return; if (k > 1 && s.turbo) s.p = [s.p[0], s.p[1], s.p[2] + 0.5 * s.r]; s.r0L4 = s.r; s.r *= k; });
    C.ech.rL = rL;
    C.ech.segL = {}; C.ech.silTypes = []; C.ech.embouts = 0;
