    var prof = [[0, 0], [0.17, 0], [0.17, 0.3], [rv, zc], [rv, 4.2], [0.15, 5.7], [rq, 5.8], [rq, 6.9], [0, 6.9]].map(function(q){ return [q[0] * S, q[1] * S]; });
