  function rIsolL4(C, r){ return r + Math.min(0.08 * r, 0.018 * C.S); }
  /* un manchon d'enveloppe autour d'un chemin de tube ; V1.2.2 (ASSEMBLER L4, verification) : matiere 'toile' (sable) et non plus 'ceram'
     (blanc, invisible sur l'inox) - comme la buche et l'anneau enveloppes */
