    if (P.turbine && P.zL1 !== undefined){ var zA = P.zL0, zB = P.zL1; col.zTurboL4 = function(k, n){ return (n > 1) ? zA + (zB - zA) * (k + 0.5) / n - 0.30 * S : (zA + zB) / 2 - 0.35 * S; }; }
