          var ox = pv[0] * o[0] * S, oy = pv[1] * o[0] * S, oz = o[1] * S;
          for (var s = r; s <= r + 1.2 * S; s += 0.02 * S){
            var q0 = [x + u[0] * s + ox, y + u[1] * s + oy, z + oz], q = [x + u[0] * (s + 0.02 * S) + ox, y + u[1] * (s + 0.02 * S) + oy, z + oz];
            if (!libreFin(coeurs, { seg: [q0, q], r: 0.001 * S }, 0)){ if (t === null || s + 0.01 * S < t) t = s + 0.01 * S; break; }
          }
