      ajout(C, 'refroidissement', 'aluF', fTour(cle('carenageT', rF, S), [[0, 0], [rF, 0], [rF, 0.55 * S], [rF * 0.35, 0.57 * S], [0, 0.57 * S]], C.seg + 8, true), mAxe([c[0], c[1], z0], [0, 0, 1]));
      ajout(C, 'refroidissement', 'noir', fCyl(rF * 0.7, rF * 0.7, 0.04 * S, C.seg), mAxe([c[0], c[1], z1 + 0.04 * S], [0, 0, 1]));
      ajout(C, 'refroidissement', 'acier', fCyl(0.30 * S, 0.30 * S, 0.12 * S, C.seg), mAxe([c[0], c[1], zP], [0, 0, 1]));
      ajout(C, 'refroidissement', 'acier', fCyl(0.08 * S, 0.08 * S, z0 - zP + 0.02 * S, 8), mAxe([c[0], c[1], (z0 + zP) / 2], [0, 0, 1]));
