    ajout(C, 'refroidissement', 'aluF', fTour(cle('carenageT', rF, S), [[0, 0], [rF, 0], [rF, 0.55 * S], [rF * 0.35, 0.57 * S], [0, 0.57 * S]], C.seg + 8, true), mAxe([O[0], O[1], z0], [0, 0, 1]));
