      ext.push(projeter(X, qo, n, lev, 0.005 * S) || [pr[0] + (qo[0] - q[0]), pr[1] + (qo[1] - q[1]), pr[2] + (qo[2] - q[2]), pr[3], pr[4], pr[5]]);
