      for (i = 0; i < nb; i++) vr.push(A1.v(rim[i][0], rim[i][1], rim[i][2], rim[i][3], rim[i][4], rim[i][5], COUL_CREUX[0], COUL_CREUX[1], COUL_CREUX[2]));
      for (i = 0; i < nb; i++) A1.t(vc, vr[i], vr[(i + 1) % nb]);
