      var rad = norme3([P0[0] - c0[0], P0[1] - c0[1], P0[2] - c0[2]]), nn = [P0[3], P0[4], P0[5]];
      var c35 = Math.cos(35 * RAD), s35 = Math.sin(35 * RAD);
      var Y = norme3([nn[0] * c35 - rad[0] * s35, nn[1] * c35 - rad[1] * s35, nn[2] * c35 - rad[2] * s35]);
      var Z = norme3([rad[0] * c35 + nn[0] * s35, rad[1] * c35 + nn[1] * s35, rad[2] * c35 + nn[2] * s35]);
