    var S = X.S, bs = baseDe(n), nb = 12, A1 = X.accH, i, lev = 0.4 * r + 0.1 * S;
    soupeLocale(c[0], c[1], c[2], r * 1.5 + 0.4 * S, filtre);
    var p0 = projeter(X, c, n, lev, 0.0025 * S) || [c[0], c[1], c[2], n[0], n[1], n[2]], vc = A1.v(p0[0], p0[1], p0[2], n[0], n[1], n[2], 1, 1, 1), vr = [];
