      for (var e = 0; e < 3 && !pr; e++){ pr = projeter(X, [c[0] + (bs[0][0] * Math.cos(a) + bs[1][0] * Math.sin(a)) * rk, c[1] + (bs[0][1] * Math.cos(a) + bs[1][1] * Math.sin(a)) * rk, c[2] + (bs[0][2] * Math.cos(a) + bs[1][2] * Math.sin(a)) * rk], n, lev, 0.0025 * S); if (!pr) rk *= 0.6; }
