          var nx = ne[0] * a + ne[3] * b + ne[6] * cc, ny = ne[1] * a + ne[4] * b + ne[7] * cc, nz = ne[2] * a + ne[5] * b + ne[8] * cc, l = Math.sqrt(nx * nx + ny * ny + nz * nz) || 1;
