    if (X.sp.signe === 'belier'){ var ca = Math.cos(8 * RAD), sa = Math.sin(8 * RAD), a0 = ay[0], a1 = ay[1]; ay = norme3([a0 * ca - a1 * sa, a0 * sa + a1 * ca, 0]); }
