        var bE = corpsNouveau({ im: imE, ii: i, geo: gE, m0: mE, r: 0.12 * S, repos: 'plat', tD: E.tD || 0, tE: 0.05, sortie: [E.d[0] * 0.3 * S, E.d[1] * 0.3 * S, E.d[2] * 0.3 * S], tourMax: 2.0, horloge: E.h, nom: 'eclat' });
        bE.dir = E.d; bE.dmin = E.dmin; bE.dmax = E.dmax; bE.autour = E.autour;
