          pt[0] = cible[0] + bsB[0][0] * cB + bsB[1][0] * sB + nB[0] * 0.02 * S; pt[1] = cible[1] + bsB[0][1] * cB + bsB[1][1] * sB + nB[1] * 0.02 * S; pt[2] = cible[2] + bsB[0][2] * cB + bsB[1][2] * sB + nB[2] * 0.02 * S;
          if (vuDe(X, _cam, pt, 0.03 * S)) nC++;
