        var x = P.x, R = x.R, k = tc >= 0.25 ? 1 : tc / 0.25, d = P.d0 + (P.d1 - P.d0) * k * k * (3 - 2 * k);
        var m = P.im.instanceMatrix.array, o = P.i * 16;
