        m[o + 8] = 0; m[o + 9] = 0; m[o + 10] = 1; m[o + 11] = 0; m[o + 12] = R.ox + R.ux * d; m[o + 13] = R.oy + R.uy * d; m[o + 14] = x.z; m[o + 15] = 1;
