        m2[o2 + 8] = 0; m2[o2 + 9] = 0; m2[o2 + 10] = 1; m2[o2 + 11] = 0; m2[o2 + 12] = P.px; m2[o2 + 13] = P.py; m2[o2 + 14] = P.z; m2[o2 + 15] = 1;
